// --- Utilities ---
export const cleanForFirestore = (obj: any, inArray = false): any => {
  if (obj === null || typeof obj !== "object") return obj;
  if (obj instanceof Date) return obj;

  const isFieldValue =
    typeof obj.isEqual === "function" && typeof obj.toDate !== "function";

  if (inArray && isFieldValue) {
    return new Date().toISOString();
  }

  // Preserve Firestore Timestamp and FieldValue objects
  if (
    typeof obj.toDate === "function" ||
    obj.isEqual ||
    (obj.constructor &&
      obj.constructor.name !== "Object" &&
      obj.constructor.name !== "Array")
  ) {
    if (
      inArray &&
      obj.constructor &&
      obj.constructor.name !== "Timestamp" &&
      obj.constructor.name !== "Object" &&
      obj.constructor.name !== "Array"
    ) {
      return new Date().toISOString();
    }
    return obj;
  }
  if (Array.isArray(obj))
    return obj.map((item) => cleanForFirestore(item, true));
  const cleaned: any = {};
  for (const key in obj) {
    const val = obj[key];
    // Remove undefined values
    if (val !== undefined) {
      cleaned[key] = cleanForFirestore(val, inArray);
    }
  }
  return cleaned;
};

export const getReportHeader = (
  profile: UserProfile | null,
  user: User | null,
  clientName: string,
  title: string,
  date?: string,
  userPlan?: any,
  clientRut?: string,
  clientAddress?: string,
) => {
  return cleanForFirestore({
    title: title || "Reporte",
    clientName: clientName || "Cliente",
    clientRut: clientRut || "",
    clientAddress: clientAddress || "",
    authorName:
      profile?.displayName || user?.displayName || user?.email || "Profesional",
    license: profile?.professionalLicense || "N/A",
    signatureURL: profile?.signatureURL || "",
    date: date || new Date().toLocaleDateString(),
    userPlan: userPlan,
  });
};

