enum OperationType {
  CREATE = "create",
  UPDATE = "update",
  DELETE = "delete",
  LIST = "list",
  GET = "get",
  WRITE = "write",
}

interface FirestoreErrorInfo {
  error: string;
  operationType: string;
  path: string | null;
  authInfo: {
    userId?: string | null;
    email?: string | null;
    emailVerified?: boolean | null;
    isAnonymous?: boolean | null;
    tenantId?: string | null;
    providerInfo?: {
      providerId?: string | null;
      email?: string | null;
    }[];
  };
}

export const handleFirestoreError = (
  error: any,
  operationType: string,
  path: string | null = null,
) => {
  const errInfo: FirestoreErrorInfo = {
    error: error instanceof Error ? error.message : String(error),
    authInfo: {
      userId: auth.currentUser?.uid,
      email: auth.currentUser?.email,
      emailVerified: auth.currentUser?.emailVerified,
      isAnonymous: auth.currentUser?.isAnonymous,
      tenantId: auth.currentUser?.tenantId,
      providerInfo:
        auth.currentUser?.providerData?.map((provider) => ({
          providerId: provider.providerId,
          email: provider.email,
        })) || [],
    },
    operationType,
    path,
  };
  console.error("Firestore Error: ", JSON.stringify(errInfo));

  // Set global error for Debug Banner
  if (typeof window !== "undefined") {
    (window as any).__LAST_FIREBASE_ERROR = errInfo;
    window.dispatchEvent(
      new CustomEvent("firebase-error", { detail: errInfo }),
    );
  }

  throw new Error(JSON.stringify(errInfo));
};

interface ErrorBoundaryState {
  hasError: boolean;
  error: any;
}

class ErrorBoundary extends React.Component<any, ErrorBoundaryState> {
  public state: ErrorBoundaryState = {
    hasError: false,
    error: null,
  };

  static getDerivedStateFromError(error: any): ErrorBoundaryState {
    return { hasError: true, error };
  }

  componentDidCatch(error: any, info: any) {
    console.error("UI Crash:", error, info);
  }

  render() {
    if (this.state.hasError) {
      return (
        <div className="p-8 bg-red-50 border-2 border-red-200 rounded-3xl m-8">
          <h2 className="text-xl font-black text-red-600 uppercase tracking-tight mb-2">
            Error Crítico de Interfaz
          </h2>
          <pre className="text-xs text-red-500 bg-white p-4 rounded-xl border border-red-100 overflow-auto max-h-40">
            {this.state.error?.message || "Algo salió mal"}
          </pre>
          <button
            onClick={() => window.location.reload()}
            className="mt-4 bg-red-600 text-white px-6 py-2 rounded-xl font-bold uppercase text-[10px] tracking-widest"
          >
            Reiniciar Aplicación
          </button>
        </div>
      );
    }
    return (this as any).props.children;
  }
}

